{
  "definition_simple": "Happening again and again, often in a way that feels boring or tiring.",
  "definition_standard": "Characterized by, involving, or containing repetition, especially to the point of monotony or tedious recurrence.",
  "pos": "adjective",
  "semantic_class": "property",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "His new job is very repetitive, but it pays well."
    },
    {
      "tier": "T1",
      "sentence": "I got bored quickly because the video game was so repetitive."
    },
    {
      "tier": "T2",
      "sentence": "Assembly line workers do repetitive tasks for hours at a time."
    },
    {
      "tier": "T2",
      "sentence": "The song has a repetitive chorus that easily gets stuck in your head."
    },
    {
      "tier": "T3",
      "sentence": "Typing without proper hand support can lead to repetitive strain injury."
    },
    {
      "tier": "T3",
      "sentence": "The editor noted that the author's descriptions were repetitive and cut several paragraphs."
    },
    {
      "tier": "T4",
      "sentence": "Automating these repetitive administrative procedures will free up staff for strategic projects."
    },
    {
      "tier": "T4",
      "sentence": "She found the daily routine of data verification dreadfully repetitive and uninspiring."
    },
    {
      "tier": "T5",
      "sentence": "The minimalist composer employed repetitive chord sequences to induce a hypnotic, meditative atmosphere."
    },
    {
      "tier": "T6",
      "sentence": "Literary critics faulted the monograph for its repetitive thematic arguments and lack of methodological rigor."
    }
  ],
  "morphological_forms": [
    {
      "form": "more repetitive",
      "label": "comparative"
    },
    {
      "form": "most repetitive",
      "label": "superlative"
    }
  ],
  "morphology_wrong_forms": {
    "more repetitive": [
      {
        "form": "repetitiver",
        "explanation": "Learners often overapply the Germanic '-er' suffix to polysyllabic adjectives ending in '-ive' rather than using the periphrastic 'more'."
      },
      {
        "form": "more repetitiver",
        "explanation": "Double-marking the comparative by pairing the adverb 'more' with the redundant suffix '-er'."
      },
      {
        "form": "repetitive-er",
        "explanation": "Attempting an unassimilated hyphenated attachment of the comparative inflection to an adjective base."
      }
    ],
    "most repetitive": [
      {
        "form": "repetitivest",
        "explanation": "Learners erroneously attach '-est' to a long adjective of Latin origin instead of premodifying with 'most'."
      },
      {
        "form": "most repetitivest",
        "explanation": "Double-marking the superlative by combining 'most' with the suffix '-est'."
      },
      {
        "form": "repetitiverest",
        "explanation": "Confusing and stacking comparative and superlative suffixes onto the base adjective."
      }
    ]
  },
  "l1_audio_confusables": [
    {
      "word": "competitive",
      "explanation": "Shares the identical prosodic rhythm and /-ɛtətɪv/ ending, differing only in the initial consonant /k/ versus /r/."
    },
    {
      "word": "repetitious",
      "explanation": "Shares the identical initial base /rɪˈpɛtɪ-/, differing only in the final derivational syllable (/-ʃəs/ instead of /-tɪv/), leading to mishearing in rapid speech."
    },
    {
      "word": "appetitive",
      "explanation": "Differs primarily by the onset /r/ versus a null/glottal onset with an open vowel, creating near-homophony in unstressed contexts."
    }
  ],
  "primary_collocate": "task",
  "collocation_distractors": [
    {
      "word": "habitual",
      "explanation": "While 'habitual' relates to repeating behaviors, it characterizes personal vices or regular customs (e.g., 'habitual smoker') rather than modifying neutral tasks or patterns."
    },
    {
      "word": "frequent",
      "explanation": "Denotes high numerical occurrence across intervals rather than the continuous, monotonous cycle denoted by 'repetitive'."
    },
    {
      "word": "cyclic",
      "explanation": "Refers to formal recurring scientific or economic cycles rather than describing tedious, reiterated actions."
    }
  ],
  "collocation_wrong_collocate": {
    "word": "frequency",
    "explanation": "While repetition relates to frequency, 'repetitive frequency' is unnatural and pleonastic in English; speakers say 'high frequency' or 'monotonous repetition'."
  },
  "cloze_distractors": [
    {
      "word": "recurring",
      "explanation": "Wrong sense: 'recurring' describes periodic events that return over time (such as expenses or dreams), not monotonous, continuous assembly work."
    },
    {
      "word": "iterative",
      "explanation": "Wrong register: 'iterative' belongs to technical, design, or computational frameworks involving incremental improvement, not routine factory labor."
    },
    {
      "word": "reluctant",
      "explanation": "Trivially unrelated: 'reluctant' describes an unwilling human mental state and cannot logically modify inanimate manual tasks."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The manager instructed the crew to work repetitive until the shipment was completed.",
      "explanation": "Grammatical category error: 'repetitive' is an adjective and cannot function adverbially to modify the verb 'work'; 'repetitively' is required."
    },
    {
      "sentence": "She has a very repetitive friend who attends our weekend book club.",
      "explanation": "Semantic selectional violation: 'repetitive' describes actions, speech, noises, or tasks, but does not modify a person directly as a character trait."
    },
    {
      "sentence": "The constant repetitive of the pneumatic drill gave residents an intense headache.",
      "explanation": "Syntactic category error: 'repetitive' is an adjective used in the nominal head position where the abstract noun 'repetition' is syntactically required."
    }
  ],
  "spot_incorrect": {
    "sentence": "During the long flight, the flight attendants performed their safety instructions repetitive for every boarding group.",
    "error_description": "The adjective 'repetitive' is erroneously used in place of the adverb 'repetitively' to modify the verb phrase 'performed their safety instructions'.",
    "corrected": "During the long flight, the flight attendants performed their safety instructions repetitively for every boarding group."
  },
  "word_family_forms": [
    {
      "form": "repetitively",
      "pos": "adverb"
    },
    {
      "form": "repetitiveness",
      "pos": "noun"
    },
    {
      "form": "repetition",
      "pos": "noun"
    },
    {
      "form": "repeat",
      "pos": "verb"
    }
  ],
  "word_family_fake_forms": [
    {
      "form": "repetitivity",
      "explanation": "Plausibly patterned after Latinate nouns like 'activity' or 'connectivity', but English uses 'repetitiveness' or 'repetition'."
    },
    {
      "form": "repetitify",
      "explanation": "Plausibly patterned after causative verbs ending in '-ify' (e.g., 'simplify'), but the standard verb is 'repeat'."
    },
    {
      "form": "repetitivate",
      "explanation": "Plausibly formed via pseudo-Latinate suffixation ('-ate'), but non-existent in standard English."
    }
  ],
